if(process.argv[2]==='build'){fs.writeFileSync('qa410-built.json',JSON.stringify(meta));console.log('QA410_BUILD '+JSON.stringify(meta));process.exit(0)}
let pid1=false;try{pid1=fs.readFileSync('/proc/1/cmdline').toString().split('\0')[0]==='/native-init'}catch{}const state={...meta,built:require('./qa410-built.json'),native_init_present:fs.existsSync('/native-init'),pid1_native_init:pid1};http.createServer((req,res)=>{res.writeHead(200,{'Content-Type':'application/json','Cache-Control':'no-store'});res.end(JSON.stringify(state))}).listen(Number(process.env.PORT),'0.0.0.0');
